const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const alsekLake = ee.Geometry.Point([-138.2, 59.4]).buffer(5000); // 5km buffer around lake

  // 2. Data Acquisition & Check
  // 1984 - Landsat 5
  let col1984 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(alsekLake)
    .filterDate('1984-06-01', '1984-09-30') // Summer months for best water detection
    .filter(ee.Filter.lt('CLOUD_COVER', 30));

  const size1984 = await col1984.size().getInfo();
  console.log(`1984 Images: ${size1984}`);

  if (size1984 === 0) {
    console.log("No data for 1984.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 2010 - Landsat 5
  let col2010 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(alsekLake)
    .filterDate('2010-06-01', '2010-09-30')
    .filter(ee.Filter.lt('CLOUD_COVER', 30));

  let size2010 = await col2010.size().getInfo();
  console.log(`2010 Images (L5): ${size2010}`);

  // Fallback to Landsat 7 if no L5 data
  if (size2010 === 0) {
    col2010 = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
      .filterBounds(alsekLake)
      .filterDate('2010-06-01', '2010-09-30')
      .filter(ee.Filter.lt('CLOUD_COVER', 30));
    size2010 = await col2010.size().getInfo();
    console.log(`2010 Images (L7): ${size2010}`);
  }

  if (size2010 === 0) {
    console.log("No data for 2010.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Cloud masking and MNDWI calculation
  function maskClouds(image) {
    const qaMask = image.select('QA_PIXEL').bitwiseAnd(parseInt('11111', 2)).eq(0);
    const saturationMask = image.select('QA_RADSAT').eq(0);
    return image.updateMask(qaMask).updateMask(saturationMask);
  }

  function addMNDWI(image) {
    const green = image.select('SR_B2').multiply(0.0000275).add(-0.2);
    const swir = image.select('SR_B5').multiply(0.0000275).add(-0.2);
    const mndwi = green.subtract(swir).divide(green.add(swir)).rename('MNDWI');
    return image.addBands(mndwi);
  }

  const img1984 = col1984.map(maskClouds).map(addMNDWI).median();
  const img2010 = col2010.map(maskClouds).map(addMNDWI).median();

  // Water mask: MNDWI > 0
  const water1984 = img1984.select('MNDWI').gt(0);
  const water2010 = img2010.select('MNDWI').gt(0);

  // 4. Calculate water extent (pixel count)
  const stats1984 = await water1984.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: alsekLake,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const stats2010 = await water2010.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: alsekLake,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const waterPixels1984 = stats1984.MNDWI;
  const waterPixels2010 = stats2010.MNDWI;

  console.log(`1984 Water pixels: ${waterPixels1984}`);
  console.log(`2010 Water pixels: ${waterPixels2010}`);

  // 5. Validation & Final Answer
  if (waterPixels1984 === null || waterPixels1984 === undefined || 
      waterPixels2010 === null || waterPixels2010 === undefined) {
    console.log("Calculation failed (null result).");
    console.log("<answer>C3</answer>");
    return;
  }

  if (waterPixels1984 === 0 && waterPixels2010 === 0) {
    console.log("No valid water pixels detected in both years.");
    console.log("<answer>C2</answer>");
    return;
  }

  const waterArea1984 = waterPixels1984 * 9; // 3000m scale = 9 km² per pixel
  const waterArea2010 = waterPixels2010 * 9;

  console.log(`1984 Water extent: ${waterArea1984.toFixed(2)} km²`);
  console.log(`2010 Water extent: ${waterArea2010.toFixed(2)} km²`);

  if (waterArea2010 < waterArea1984) {
    console.log("Water extent decreased between 1984 and 2010.");
    console.log("<answer>A</answer>");
  } else {
    console.log("Water extent did not decrease between 1984 and 2010.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
